package main.rice.node;

import main.rice.obj.AIterablePyObj;
import main.rice.obj.APyObj;

import java.util.*;

/**
 * An abstract class whose instances represent generators of iterable Python objects.
 *
 * @param <OuterType> the outer type of object generated by this node
 * @param <InnerType> the type of object generated by the leftChild node, which represents
 *                    the type of elements in this iterable object; if we call
 *                    this.leftChild.genExVals(), it will return a Set<InnerType>
 */
public abstract class AIterablePyNode<OuterType extends AIterablePyObj<InnerType>,
        InnerType extends APyObj<?>> extends APyNode<OuterType> {
    // TODO: implement the abstract AIterablePyNode class here

    /**
     * Field representing the left child of the iterable PyNode object.
     */
    protected APyNode<InnerType> leftChild;

    /**
     * Returns the left child node.
     * @return the left child node.
     */
    @Override
    public APyNode<InnerType> getLeftChild() {
        return this.leftChild;
    }


    /**
     * Generates all valid PyObjs of type OuterType within the exhaustive domain.
     * @return a set of PyObjs of type OuterType within the exhaustive domain.
     */
    public Set<OuterType> genExVals() {
        //Find the maximum value in exDomain.
        List<? extends Number> exDomainCopy = this.getExDomain();
        List<Integer> exDomainInts = new ArrayList<>();
        for (Number len : exDomainCopy) {
            int temp = len.intValue();
            exDomainInts.add(temp);
        }
        int maxVal = Collections.max(exDomainInts);

        //Recursive calls to generate inner type's exhaustive values and to generate all possible permutations.
        Set<InnerType> childGenExVals = this.chooseChildExVals();
        Set<List<InnerType>> helper = this.genExValsRecHelper(maxVal, childGenExVals);

        return this.genExValsProc(helper);

    }

    /**
     * Generates a single valid PyObj of type OuterType within the random domain.
     * @return a single PyObj of type OuterType selected from the random domain.
     */
    public OuterType genRandVal() {
        List<InnerType> listInner = new ArrayList<>();

        //Get a random length from ranDomain and add random inner type values to the list.
        int len = this.ranDomainChoice().intValue();
        for (int i = 0; i < len; i++) {
            listInner.add(this.chooseChildRandVal());
        }

        return genRandValProc(listInner);

    }


    /**
     * Recursive helper function for genExVals that generates all possible permutations of InnerType with lengths up to maxVal given by OuterType.
     * @param maxValue the max length given by OuterType.
     * @param childGenExVals the set of children values to be added to the permutations.
     * @return a set of lists representing all possible permutations of InnerType with length from 0 to maxValue.
     */
    protected Set<List<InnerType>> genExValsRecHelper(int maxValue, Set<InnerType> childGenExVals) {
        //Base case when length is zero.
        if (maxValue == 0) {
            return new HashSet<>(Set.of(new ArrayList<>()));
        }
        //Recursive case when length is greater than zero.
        else {
            //Accumulate all permutations with lengths up to maxValue.
            Set<List<InnerType>> allPerms = new HashSet<>(Set.of(new ArrayList<>()));
            //Recursive call to this function using maxValue-1 to get the smaller permutations.
            Set<List<InnerType>> smallPerms = genExValsRecHelper(maxValue - 1, childGenExVals);

            //Generate new larger permutations from the smaller permutations.
            for (List<InnerType> smallPerm : smallPerms) {
                for (InnerType val : childGenExVals) {
                    //For each smaller permutation, make a copy of the permutation and add a value from childGenExVals to it, then add the new permutation to allPerms.
                    List<InnerType> newPerm = new ArrayList<>(smallPerm);
                    newPerm.add(val);
                    allPerms.add(newPerm);
                }
            }
            return allPerms;
        }
    }

    /**
     * Helper function for generating the exhaustive values of the inner type. PyStringNode overrides this function.
     * @return a set of type InnerType representing the exhaustive values of the inner type.
     */
    protected Set<InnerType> chooseChildExVals() {
        return this.getLeftChild().genExVals();
    }

    /**
     * Helper function for generating a random value of the inner type. PyStringNode overrides this function.
     * @return an InnerType object representing a random value of the inner type.
     */
    protected InnerType chooseChildRandVal() {
        return this.getLeftChild().genRandVal();
    }

    /**
     * Helper function for post-processing and creating the actual instances of the exhaustive values.
     * @param helper a set of lists representing all possible permutations.
     * @return a set of type OuterType representing the set of valid objects of the specific PyObj type within the exhaustive domain.
     */
    protected abstract Set<OuterType> genExValsProc(Set<List<InnerType>> helper);

    /**
     * Helper function for post-processing and creating the actual instance of a random value.
     * @param listInner a list of type InnerType representing the random value to be passed to constructing the PyObj.
     * @return a single PyObj of type OuterType selected from the random domain.
     */
    protected abstract OuterType genRandValProc(List<InnerType> listInner);

}
